cql:
library TWCDIOverview version '1.0.0'
using FHIR version '4.0.1'
include FHIRHelpers version '4.0.1' called FHIRHelpers

// Taiwan Core Data for Interoperability - All 20 Data Classes

codesystem "ObservationCategory": 'http://terminology.hl7.org/CodeSystem/observation-category'
code "vital-signs": 'vital-signs' from "ObservationCategory"
code "laboratory": 'laboratory' from "ObservationCategory"

context Patient

// 1. Demographics
define "Patient Info":
  Patient P
    return {
      id: P.id.value,
      gender: P.gender.value,
      birthDate: P.birthDate.value,
      name: P.name[0].text.value
    }

// 2. Encounters
define "All Encounters":
  [Encounter] E
    return {
      id: E.id.value,
      status: E.status.value,
      class: E.class.display.value,
      type: E.type[0].text.value,
      period_start: E.period."start".value
    }
    sort by period_start desc

// 3. Conditions / Diagnoses
define "All Conditions":
  [Condition] C
    return {
      id: C.id.value,
      code: C.code.text.value,
      clinicalStatus: C.clinicalStatus.coding[0].code.value,
      verificationStatus: C.verificationStatus.coding[0].code.value,
      recordedDate: C.recordedDate.value
    }
    sort by recordedDate desc

// 4. Vital Signs
define "Vital Signs":
  [Observation] O
    where exists (O.category Cat where Cat ~ "vital-signs")
      and O.status in { 'final', 'amended', 'corrected' }
    return {
      id: O.id.value,
      code: O.code.text.value,
      value: (O.value as Quantity).value.value,
      unit: (O.value as Quantity).unit.value,
      issued: O.issued.value
    }
    sort by issued desc

// 5. Laboratory Results
define "Lab Results":
  [Observation] O
    where exists (O.category Cat where Cat ~ "laboratory")
      and O.status in { 'final', 'amended', 'corrected' }
    return {
      id: O.id.value,
      code: O.code.text.value,
      value: (O.value as Quantity).value.value,
      unit: (O.value as Quantity).unit.value,
      issued: O.issued.value
    }
    sort by issued desc

// 6. Medication Requests
define "Medication Orders":
  [MedicationRequest] M
    return {
      id: M.id.value,
      medication: (M.medication as CodeableConcept).text.value,
      status: M.status.value,
      intent: M.intent.value,
      authoredOn: M.authoredOn.value
    }
    sort by authoredOn desc

// 7. Medication Statements
define "Medication Usage":
  [MedicationStatement] M
    return {
      id: M.id.value,
      medication: (M.medication as CodeableConcept).text.value,
      status: M.status.value
    }

// 8. Medications
define "Medications":
  [Medication] M
    return {
      id: M.id.value,
      code: M.code.text.value
    }

// 9. Procedures
define "All Procedures":
  [Procedure] P
    return {
      id: P.id.value,
      code: P.code.text.value,
      status: P.status.value
    }

// 10. Diagnostic Reports
define "Diagnostic Reports":
  [DiagnosticReport] D
    return {
      id: D.id.value,
      code: D.code.text.value,
      status: D.status.value,
      issued: D.issued.value
    }
    sort by issued desc

// 11. Allergies
define "Allergies":
  [AllergyIntolerance] A
    return {
      id: A.id.value,
      code: A.code.text.value,
      clinicalStatus: A.clinicalStatus.coding[0].code.value,
      criticality: A.criticality.value
    }

// 12. Immunizations
define "Immunizations":
  [Immunization] I
    where I.status = 'completed'
    return {
      id: I.id.value,
      vaccine: I.vaccineCode.text.value,
      status: I.status.value
    }

// 13-20. Other Resources
define "Organizations":
  [Organization] O return { id: O.id.value, name: O.name.value }

define "Practitioners":
  [Practitioner] P return { id: P.id.value, name: P.name[0].text.value }

define "Imaging Studies":
  [ImagingStudy] IS return { id: IS.id.value, status: IS.status.value }

define "Locations":
  [Location] L return { id: L.id.value, name: L.name.value }

define "Compositions":
  [Composition] C return { id: C.id.value, title: C.title.value }

define "Document References":
  [DocumentReference] D return { id: D.id.value, description: D.description.value }
